using System.ComponentModel.Composition;
using XrmToolBox.Extensibility;
using XrmToolBox.Extensibility.Interfaces;

namespace Formula81.XrmToolBox.Tools.MetaScanner
{
    [Export(typeof(IXrmToolBoxPlugin)),
        ExportMetadata("Name", "Meta Scanner"),
        ExportMetadata("Description", "Find any table, column, choice or relationship in your Dataverse metadata, fast"),
        // 32x32 pixels
        ExportMetadata("SmallImageBase64", ""),
        // 80x80 pixels
        ExportMetadata("BigImageBase64", ""),
        ExportMetadata("BackgroundColor", "#FF8000"),
        ExportMetadata("PrimaryFontColor", "White"),
        ExportMetadata("SecondaryFontColor", "Black")]
